<script setup lang="ts">
import {Check,Flag,ChevronRight} from 'lucide-vue-next'
import type {ScriptProgress} from './types'

const phases={selected:'已选择结局 · 善后待办',resolving:'善后进行中',resolved:'善后已完成',legacy_unverified:'旧版结局 · 后果未核验'}
defineProps<{progress:ScriptProgress}>()
</script>
<template><section class="plot-progress"><div class="plot-count"><Flag :size="19"/><strong>{{progress.ending?.phase==='resolved'?'故事已完成':'故事进展'}}</strong><span>主线 {{progress.completedCount}} / {{progress.totalCount}}</span></div><progress :value="progress.completedCount" :max="progress.totalCount" aria-label="故事任务进度"></progress><p v-if="progress.currentSummary">{{progress.currentSummary}}</p><p v-for="item in progress.confirmedHoldings" :key="item.itemName">{{item.itemName}}：{{item.description}}</p><article v-if="progress.ending" class="plot-ending"><Flag :size="26"/><small>{{phases[progress.ending.phase||'legacy_unverified']}}</small><h2>{{progress.ending.title}}</h2><p>{{progress.ending.description}}</p><small v-if="progress.resolution?.resolvedAtCheckpointId">本结局记录完成节点的结果；后续行动以当前资料为准。</small></article><section v-if="progress.resolution?.totalCount" aria-label="结局善后"><strong>善后 {{progress.resolution.completedCount}} / {{progress.resolution.totalCount}}</strong><article v-for="step in progress.resolution.steps" :key="step.id" class="plot-objective" :class="{completed:step.completed}"><Check v-if="step.completed" :size="17"/><ChevronRight v-else :size="17"/><div><strong>{{step.title}}</strong><small> · {{step.completed?'已完成':step.available?'待办理':'等待前置'}}{{step.origin==='adaptation'?' · 改编善后':''}}</small><p>{{step.description}}</p></div></article></section><article v-for="objective in progress.objectives" :key="objective.id" class="plot-objective" :class="{completed:objective.completed}"><Check v-if="objective.completed" :size="17"/><ChevronRight v-else :size="17"/><div><strong>{{objective.title}}</strong><p>{{objective.description}}</p></div></article></section></template>
<style scoped>.plot-count{display:flex;align-items:center;gap:9px}.plot-count>span{margin-left:auto;color:var(--muted,#817a6d);font-size:13px}.plot-progress>progress{width:100%;height:4px;margin:22px 0}.plot-objective{display:flex;align-items:flex-start;gap:12px;border-bottom:1px solid var(--border,#e7decf);padding:20px 0}.plot-objective>svg{flex-shrink:0;margin-top:2px;color:var(--accent,#ad5830)}.plot-objective p{font-size:14px;line-height:1.8;color:var(--muted,#817a6d);margin-bottom:0}.plot-objective.completed{opacity:.7}.plot-ending{padding:25px;background:#f2e5d5;border-radius:14px;margin-bottom:12px;color:#694123}.plot-ending h2{font:24px var(--font-serif,serif)}.plot-ending p{font-size:15px;line-height:1.9}</style>
